<script setup>
import { ref, reactive, computed, watch, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { renderMarkdown, checkpoints, imageIds } from './markdown'
const page=ref(location.hash.slice(1)||'overview'), mobileOpen=ref(false), loading=ref(true), error=ref(''), busy=ref(false)
const tasks=ref([]), submissions=ref([]), achievements=ref([])
const dashboard=reactive({coins:0,completedTasks:0,totalTasks:0,publishedTasks:0,streak:0,week:[],recent:[]})
const settings=reactive({theme:'light',accent:'#238636',compact_mode:false})
const agent=reactive({provider:'openai-compatible',endpoint:'',model:'',enabled:false,has_api_key:false,system_prompt:''})
const apiKey=ref(''), publishToken=ref(''), settingsTab=ref('appearance'), search=ref(''), filter=ref('all'), detail=ref(null)
const editor=reactive(blankTask()), previewMode=ref('split'), markdownInput=ref(null), assets=ref([]), uploading=ref(false), fileInput=ref(null), imageInput=ref(null), proofInput=ref(null)
const proofAssets=ref([]), answer=ref(''), testOutput=ref(''), checkedIds=ref([]), submitBusy=ref(false)
const generateOpen=ref(false), generateBusy=ref(false), generator=reactive({topic:'',subject:'前端开发',difficulty:'入门',count:3})
const coinOpen=ref(false), coins=reactive({total:0,transactions:[]}), autosaved=ref(''), restored=ref(false)
let draftTimer
const categories=['前端开发','JavaScript','后端开发','数据库','计算机基础','英语学习','阅读与写作','其他']
const nav=[{key:'overview',label:'学习总览',icon:'grid-1x2'},{key:'tasks',label:'学习任务',icon:'journal-code'},{key:'reviews',label:'提交与错题',icon:'patch-check'},{key:'achievements',label:'成长与成就',icon:'trophy'},{key:'admin',label:'管理工作台',icon:'sliders2'}]
const pageTitle=computed(()=>({overview:'学习总览',tasks:'学习任务',detail:'任务详情',editor:editor.id?'编辑任务':'新建任务',reviews:'提交与错题',achievements:'成长与成就',admin:'管理工作台',settings:'偏好设置'})[page.value]||'学习总览')
const completedIds=computed(()=>new Set([...tasks.value.filter(t=>t.completed).map(t=>t.id),...submissions.value.filter(s=>s.status==='completed').map(s=>s.task_id)]))
const visibleTasks=computed(()=>tasks.value.filter(t=>(filter.value==='all'||(filter.value==='completed'?completedIds.value.has(t.id):filter.value==='published'?t.status==='published'&&!completedIds.value.has(t.id):t.status==='draft'))&&`${t.title} ${t.subject} ${t.content}`.toLowerCase().includes(search.value.toLowerCase())))
const activeTasks=computed(()=>tasks.value.filter(t=>t.status==='published'&&!completedIds.value.has(t.id)))
const unlockedCount=computed(()=>achievements.value.filter(a=>a.unlocked).length)
const taskCheckpoints=computed(()=>checkpoints(detail.value?.content))
const progress=computed(()=>tasks.value.filter(t=>t.status==='published').length?Math.round(tasks.value.filter(t=>t.status==='published'&&completedIds.value.has(t.id)).length/tasks.value.filter(t=>t.status==='published').length*100):0)
const greeting=computed(()=>new Date().getHours()<12?'上午好':new Date().getHours()<18?'下午好':'晚上好')
const today=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())
const reviewCounts=computed(()=>({pending:submissions.value.filter(s=>s.status==='pending').length,revision:submissions.value.filter(s=>s.status==='needs_revision').length}))
function blankTask(){return{id:null,title:'',description:'',subject:'前端开发',difficulty:'入门',status:'draft',points:40,duration:30,content:'# 学习目标\n\n写下你希望掌握的知识。\n\n## 动手练习\n\n- [ ] 完成练习并验证结果\n\n<!-- sf:checkpoint id="practice" title="完成练习，提交截图或测试结果" -->\n',success_criteria:'',proof_types:['screenshot','test']}}
async function api(path,options={}){const res=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(!res.ok){let data;try{data=await res.json()}catch{}throw new Error(data?.message||`请求失败 (${res.status})`)}return res.status===204?null:res.json()}
async function refresh(){error.value='';try{const [t,d,s,a]=await Promise.all([api('/tasks'),api('/dashboard'),api('/submissions'),api('/achievements')]);tasks.value=t.items;Object.assign(dashboard,d);submissions.value=s.items;achievements.value=a.items}catch(e){error.value=e.message}finally{loading.value=false}}
function go(key){page.value=key;mobileOpen.value=false;location.hash=key;window.scrollTo({top:0,behavior:'smooth'})}
function onHash(){const key=location.hash.slice(1);if(nav.some(n=>n.key===key)||key==='settings')page.value=key}
function status(task){return completedIds.value.has(task.id)?'completed':task.status}
function statusText(value){return({draft:'草稿',published:'进行中',completed:'已完成',pending:'待评审',needs_revision:'待改进',error:'评审失败'})[value]||value}
function tagType(value){return({draft:'info',published:'primary',completed:'success',pending:'warning',needs_revision:'warning',error:'danger'})[value]||'info'}
function date(value){if(!value)return '—';const d=new Date(value.includes('T')?value:`${value.replace(' ','T')}Z`);return Number.isNaN(+d)?value:new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d)}
function taskIcon(t){return t.subject?.includes('英语')?'translate':t.subject?.includes('数据')?'database':t.subject?.includes('阅读')?'book':'code-slash'}
async function openTask(t){try{detail.value=await api(`/tasks/${t.id}`);answer.value='';testOutput.value='';proofAssets.value=[];checkedIds.value=[];go('detail')}catch(e){ElMessage.error(e.message)}}
function newTask(){Object.assign(editor,blankTask());assets.value=[];restored.value=false;previewMode.value='split';go('editor')}
async function editTask(t){Object.assign(editor,blankTask(),JSON.parse(JSON.stringify(t)));assets.value=[];await loadAssets();restored.value=false;go('editor')}
async function loadAssets(){assets.value=(await Promise.all(imageIds(editor.content).map(id=>api(`/uploads/${id}`).catch(()=>null)))).filter(Boolean)}
async function saveTask(publish){if(!editor.title.trim())return ElMessage.warning('请填写任务标题');if(!editor.content.trim())return ElMessage.warning('请填写任务正文');busy.value=true;try{const payload={...editor,status:publish?'published':'draft'};delete payload.id;delete payload.submissions;const result=await api(editor.id?`/tasks/${editor.id}`:'/tasks',{method:editor.id?'PUT':'POST',body:JSON.stringify(payload)});Object.assign(editor,result);clearTimeout(draftTimer);localStorage.removeItem('learnledger-draft');autosaved.value='已保存到数据库';await refresh();ElMessage.success(publish?'任务已发布，可以开始学习':'草稿已保存');if(publish)go('tasks')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function deleteTask(t){try{await ElMessageBox.confirm(`删除“${t.title}”及其提交记录？已获得金币将保留在账本中。`,'删除任务',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await api(`/tasks/${t.id}`,{method:'DELETE'});await refresh();ElMessage.success('任务已删除');if(page.value==='detail')go('tasks')}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
function insert(text){const el=markdownInput.value;const start=el?.selectionStart??editor.content.length;const end=el?.selectionEnd??start;editor.content=editor.content.slice(0,start)+text+editor.content.slice(end);nextTick(()=>{el?.focus();el?.setSelectionRange(start+text.length,start+text.length)})}
function wrap(before,after=before){const el=markdownInput.value;const selection=el?editor.content.slice(el.selectionStart,el.selectionEnd):'';insert(`${before}${selection||'文本'}${after}`)}
function addCheckpoint(){let index=checkpoints(editor.content).length+1;while(checkpoints(editor.content).some(c=>c.id===`step-${index}`))index++;insert(`\n<!-- sf:checkpoint id="step-${index}" title="填写验收要求" -->\n`)}
async function importMd(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('Markdown 文件不能超过 1 MB');if(editor.title||editor.content!==blankTask().content)await ElMessageBox.confirm('导入会替换当前任务正文，继续导入？','导入 Markdown',{confirmButtonText:'导入',cancelButtonText:'取消'});editor.content=await file.text();if(!editor.title)editor.title=file.name.replace(/\.(md|markdown)$/i,'');await loadAssets();ElMessage.success('Markdown 已导入')}catch(e){if(e instanceof Error)ElMessage.error(e.message)}finally{event.target.value=''}}
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('文件读取失败'));r.readAsDataURL(file)})}
async function upload(file){if(!/^image\/(png|jpeg|gif|webp)$/.test(file.type))throw new Error('支持 PNG、JPG、GIF、WebP 图片');if(file.size>5*1024*1024)throw new Error('单张图片不能超过 5 MB');const dataUrl=await readFile(file);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('图片无法解码'));img.src=dataUrl});const result=await api('/uploads',{method:'POST',body:JSON.stringify({name:file.name,dataUrl})});return {...result,displayWidth:Math.min(img.naturalWidth,600)}}
async function addImages(files){uploading.value=true;try{for(const file of files){const asset=await upload(file);assets.value.push(asset);insert(`\n[[image:${asset.id}|width=${asset.displayWidth}]]\n`)}ElMessage.success('图片已保存并转换为占位符')}catch(e){ElMessage.error(e.message)}finally{uploading.value=false}}
async function onImage(event){await addImages([...event.target.files||[]]);event.target.value=''}
async function onPaste(event){const files=[...event.clipboardData?.files||[]].filter(f=>f.type.startsWith('image/'));if(files.length){event.preventDefault();await addImages(files)}}
async function onDrop(event){const files=[...event.dataTransfer?.files||[]].filter(f=>f.type.startsWith('image/'));if(files.length){event.preventDefault();await addImages(files)}}
function imageWidth(asset){const m=[...editor.content.matchAll(/\[\[image:([a-zA-Z0-9-]+)(?:\|width=(\d+))?\]\]/g)].find(m=>m[1]===asset.id);return Number(m?.[2])||600}
function resizeImage(asset,value){if(!Number.isInteger(value)||value<40||value>2400)return;editor.content=editor.content.replace(new RegExp(`\\[\\[image:${asset.id}(?:\\|width=\\d+)?\\]\\]`,'g'),`[[image:${asset.id}|width=${value}]]`)}
async function addProof(event){if(proofAssets.value.length+(event.target.files?.length||0)>6){event.target.value='';return ElMessage.warning('每次提交最多上传 6 张截图')}uploading.value=true;try{for(const f of event.target.files||[])proofAssets.value.push(await upload(f))}catch(e){ElMessage.error(e.message)}finally{uploading.value=false;event.target.value=''}}
async function submit(){if(!proofAssets.value.length&&!testOutput.value.trim())return ElMessage.warning('请上传截图或填写测试输出');if(taskCheckpoints.value.some(c=>!checkedIds.value.includes(c.id)))return ElMessage.warning('请逐项确认已完成检查点');submitBusy.value=true;try{const result=await api(`/tasks/${detail.value.id}/submit`,{method:'POST',body:JSON.stringify({answer:answer.value,test_output:testOutput.value,attachment_ids:proofAssets.value.map(a=>a.id),checkpoint_ids:checkedIds.value})});ElMessage[result.status==='completed'?'success':result.status==='error'?'error':'info'](result.status==='completed'?`任务通过！获得 ${result.earnedCoins||0} 金币`:result.feedback||'提交已保存');detail.value=await api(`/tasks/${detail.value.id}`);await refresh()}catch(e){ElMessage.error(e.message)}finally{submitBusy.value=false}}
async function retry(s){submitBusy.value=true;try{const result=await api(`/submissions/${s.id}/retry`,{method:'POST'});ElMessage.info(result.feedback||'评审已更新');await refresh();if(detail.value)detail.value=await api(`/tasks/${detail.value.id}`)}catch(e){ElMessage.error(e.message)}finally{submitBusy.value=false}}
async function saveSettings(){busy.value=true;try{await api('/settings',{method:'PUT',body:JSON.stringify(settings)});ElMessage.success('偏好设置已保存')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function saveAgent(){busy.value=true;try{const payload={...agent};if(apiKey.value)payload.api_key=apiKey.value;Object.assign(agent,await api('/agent/config',{method:'PUT',body:JSON.stringify(payload)}));apiKey.value='';ElMessage.success('Agent 配置已保存')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function loadToken(){try{publishToken.value=(await api('/agent/publish-token')).token}catch(e){ElMessage.error(e.message)}}
async function generate(){if(!generator.topic.trim())return ElMessage.warning('请输入学习目标');generateBusy.value=true;try{const result=await api('/agent/generate',{method:'POST',body:JSON.stringify(generator)});ElMessage.success(`已生成 ${result.items?.length||0} 个任务草稿，请检查后发布`);generateOpen.value=false;await refresh()}catch(e){ElMessage.error(e.message)}finally{generateBusy.value=false}}
async function showCoins(){try{Object.assign(coins,await api('/coins'));coinOpen.value=true}catch(e){ElMessage.error(e.message)}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
async function exportData(){try{download(JSON.stringify(await api('/export'),null,2),`learnledger-${new Date().toISOString().slice(0,10)}.json`,'application/json')}catch(e){ElMessage.error(e.message)}}
function exportMd(){download(editor.content,`${editor.title||'学习任务'}.md`,'text/markdown;charset=utf-8')}
async function copy(value){try{await navigator.clipboard.writeText(value);ElMessage.success('已复制')}catch{ElMessage.warning('浏览器暂不支持复制，请手动选中文字')}}
function applyTheme(){document.documentElement.classList.toggle('dark',settings.theme==='dark');document.documentElement.dataset.density=settings.compact_mode?'compact':'comfortable';const root=document.documentElement;const color=/^#[\da-f]{6}$/i.test(settings.accent)?settings.accent:'#238636';root.style.setProperty('--accent',color);root.style.setProperty('--accent-soft',`color-mix(in srgb, ${color} 10%, var(--surface))`);root.style.setProperty('--el-color-primary',color);const rgb=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16));for(let n=1;n<10;n++){const base=settings.theme==='dark'?20:255;root.style.setProperty(`--el-color-primary-light-${n}`,`rgb(${rgb.map(c=>Math.round(c+(base-c)*n/10)).join(',')})`)}root.style.setProperty('--el-color-primary-dark-2',`rgb(${rgb.map(c=>Math.round(c*.8)).join(',')})`);localStorage.setItem('learnledger-appearance',JSON.stringify(settings))}
watch(settings,applyTheme,{deep:true})
watch(editor,()=>{if(page.value!=='editor')return;clearTimeout(draftTimer);draftTimer=setTimeout(()=>{localStorage.setItem('learnledger-draft',JSON.stringify(editor));autosaved.value='本地草稿已暂存'},600)},{deep:true})
function restoreDraft(){try{Object.assign(editor,JSON.parse(localStorage.getItem('learnledger-draft')));loadAssets();restored.value=false;go('editor')}catch{ElMessage.warning('没有可恢复的草稿')}}
onMounted(async()=>{window.addEventListener('hashchange',onHash);try{Object.assign(settings,JSON.parse(localStorage.getItem('learnledger-appearance')||'{}'))}catch{}applyTheme();await refresh();const loaded=await Promise.allSettled([api('/settings'),api('/agent/config')]);if(loaded[0].status==='fulfilled')Object.assign(settings,loaded[0].value);if(loaded[1].status==='fulfilled')Object.assign(agent,loaded[1].value);restored.value=!!localStorage.getItem('learnledger-draft');if(['detail','editor'].includes(page.value))go('overview')})
onBeforeUnmount(()=>{window.removeEventListener('hashchange',onHash);clearTimeout(draftTimer)})
</script>
<template>
<div class="app-shell">
  <aside class="sidebar" :class="{open:mobileOpen}">
    <a class="brand" href="#overview" @click="go('overview')"><span class="brand-mark"><i class="bi bi-journal-check"></i></span><span><strong class="brand-name">知序 <small>LearnLedger</small></strong><span class="brand-sub">让每一步学习，有迹可循</span></span></a>
    <div class="workspace-label"><span class="avatar small">知</span><span>我的学习空间</span><span class="local-badge">LOCAL</span></div>
    <nav class="nav-list"><p class="nav-section-label">个人工作台</p><button v-for="item in nav" :key="item.key" class="nav-item" :class="{active:page===item.key||(item.key==='tasks'&&['detail','editor'].includes(page))}" @click="go(item.key)"><i :class="`bi bi-${item.icon}`"></i><span>{{ item.label }}</span><span v-if="item.key==='tasks'" class="nav-count">{{ tasks.length }}</span><span v-if="item.key==='reviews'&&reviewCounts.revision" class="nav-count">{{ reviewCounts.revision }}</span></button></nav>
    <div class="sidebar-bottom"><div class="streak-card"><i class="bi bi-fire"></i><div><strong>连续学习 {{ dashboard.streak||0 }} 天</strong><span>每一个小进步，都算数</span></div></div><button class="nav-item" :class="{active:page==='settings'}" @click="go('settings')"><i class="bi bi-gear"></i><span>偏好设置</span></button><div class="sidebar-footer"><span><i class="bi bi-circle-fill"></i> SQLite 本地存储</span><span>v1.0</span></div></div>
  </aside>
  <button v-if="mobileOpen" class="sidebar-overlay" aria-label="关闭菜单" @click="mobileOpen=false"></button>
  <main class="main-content">
    <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="展开菜单" @click="mobileOpen=!mobileOpen"><i class="bi bi-list"></i></button><span>我的空间</span><i class="bi bi-chevron-right"></i><strong>{{ pageTitle }}</strong></div><div class="top-actions"><button class="coin-pill" @click="showCoins"><i class="bi bi-coin"></i>{{ dashboard.coins||0 }}<span>金币</span></button><button class="icon-button" :aria-label="settings.theme==='dark'?'切换浅色模式':'切换深色模式'" @click="settings.theme=settings.theme==='dark'?'light':'dark'"><i :class="`bi bi-${settings.theme==='dark'?'sun':'moon'}`"></i></button><span class="avatar">知</span></div></header>
    <div v-if="error" class="error-banner"><i class="bi bi-exclamation-triangle"></i><span>{{ error }}。请确认 API 服务已启动。</span><el-button size="small" @click="refresh">重试</el-button></div>
    <div v-if="loading" class="loading-shell"><el-skeleton :rows="8" animated/></div>
    <div v-else class="page" :class="`${page}-page`">
      <template v-if="page==='overview'">
        <div class="page-heading"><div><p class="eyebrow">{{ today }} · KEEP LEARNING</p><h1>{{ greeting }}，学习者 <span class="wave">☀</span></h1><p class="muted">不必一次走很远，今天也向前一步。</p></div><el-button type="primary" @click="newTask"><i class="bi bi-plus-lg"></i> 新建学习任务</el-button></div>
        <div v-if="restored" class="draft-banner"><i class="bi bi-file-earmark-text"></i> 你有一份未发布的本地草稿。<el-button text type="primary" @click="restoreDraft">继续编辑</el-button></div>
        <section class="hero-banner"><div class="hero-copy"><span class="hero-tag"><i class="bi bi-stars"></i> 把知识变成你的能力</span><h2>小目标，积累大改变。</h2><p>选择一个任务，动手练习，提交你的学习证据。<br/>让 AI 教练陪你把“学过了”变成“学会了”。</p><el-button type="primary" @click="activeTasks.length?openTask(activeTasks[0]):newTask()">{{ activeTasks.length?'继续学习':'创建第一个目标' }} <i class="bi bi-arrow-right"></i></el-button><span class="hero-footnote">{{ activeTasks.length }} 个任务等你探索</span></div><div class="hero-illustration" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="illustration-window"><div class="window-dots"><b></b><b></b><b></b><span>learning.md</span></div><div class="illustration-code"><span class="code-heading"># 今天，也在进步</span><span><b>✓</b> 保持好奇</span><span><b>✓</b> 动手实践</span><span><i class="bi bi-circle"></i> 解锁下一种可能</span><div class="code-progress"><i></i></div></div></div><span class="floating-medal"><i class="bi bi-award"></i></span><span class="floating-check"><i class="bi bi-check-lg"></i></span></div></section>
        <div class="stats-grid"><button class="stat-card" @click="showCoins"><span class="stat-icon gold"><i class="bi bi-coin"></i></span><span><small>我的金币</small><strong>{{ dashboard.coins||0 }}<em>枚</em></strong><span class="stat-note">努力积累的每一份奖励</span></span><i class="bi bi-arrow-up-right stat-arrow"></i></button><div class="stat-card"><span class="stat-icon green"><i class="bi bi-check2-circle"></i></span><div><small>完成任务</small><strong>{{ dashboard.completedTasks||0 }}<em>/ {{ tasks.filter(t=>t.status==='published').length }}</em></strong><span class="stat-note">每一次完成，都是进步</span></div></div><div class="stat-card"><span class="stat-icon blue"><i class="bi bi-journal-code"></i></span><div><small>进行中的任务</small><strong>{{ activeTasks.length }}<em>个</em></strong><span class="stat-note">从一个小目标开始</span></div></div><button class="stat-card" @click="go('achievements')"><span class="stat-icon purple"><i class="bi bi-trophy"></i></span><span><small>成就徽章</small><strong>{{ unlockedCount }}<em>/ {{ achievements.length }}</em></strong><span class="stat-note">收集属于你的成长印记</span></span><i class="bi bi-arrow-up-right stat-arrow"></i></button></div>
        <div class="overview-grid"><div class="main-column"><section class="panel"><div class="panel-header"><div><h2><i class="bi bi-journal-text"></i> 接下来，学什么</h2><p>保持专注，从这里继续</p></div><button class="link-button" @click="go('tasks')">查看全部 <i class="bi bi-arrow-right"></i></button></div><div v-for="task in activeTasks.slice(0,4)" :key="task.id" class="task-row" role="button" tabindex="0" @click="openTask(task)" @keydown.enter="openTask(task)"><span class="task-check"><i class="bi bi-circle"></i></span><div class="task-main"><strong>{{ task.title }}</strong><span><i class="bi bi-folder2"></i> {{ task.subject }} <b>·</b> {{ task.duration||30 }} 分钟 <b>·</b> {{ task.difficulty }}</span></div><span class="task-reward"><i class="bi bi-coin"></i> +{{ task.points }}</span><i class="bi bi-chevron-right row-arrow"></i></div><div v-if="!activeTasks.length" class="empty-state"><i class="bi bi-journal-check"></i><strong>新的知识，等你开启</strong><p>创建或发布一个任务，开始记录学习。</p><el-button @click="newTask">创建任务</el-button></div></section><section class="panel activity-panel"><div class="panel-header"><div><h2><i class="bi bi-calendar3"></i> 学习足迹</h2><p>过去 7 天的任务完成记录</p></div><span class="subtle">每一点绿，都是积累</span></div><div class="week-bars"><div v-for="day in dashboard.week||[]" :key="day.date" class="day-bar"><span class="bar-count">{{ day.count }}</span><div class="bar-track"><span :style="{height:Math.max(day.count?15:3,day.count/Math.max(1,...dashboard.week.map(d=>d.count))*100)+'%'}"></span></div><small>{{ day.date?.slice(5) }}</small></div></div></section></div><div class="side-column"><section class="panel progress-card"><div class="panel-header"><h2>学习进度</h2><i class="bi bi-pie-chart muted"></i></div><el-progress type="dashboard" :percentage="progress" :color="settings.accent" :width="156" :stroke-width="9"><span class="ring-number">{{ progress }}<small>%</small></span><span class="ring-caption">已发布任务完成率</span></el-progress><div class="progress-summary"><span><i class="bi bi-circle-fill"></i> 已完成 <b>{{ completedIds.size }}</b></span><span>待完成 <b>{{ activeTasks.length }}</b></span></div></section><section class="panel coach-card"><span class="coach-icon"><i class="bi bi-robot"></i></span><h3>你的 AI 学习教练</h3><p>{{ agent.enabled?'提交截图或测试结果，获取完成评审与针对性的错题分析。':'连接你的 Agent，让每次练习都能获得具体反馈。' }}</p><div class="connection-state" :class="{connected:agent.enabled}"><i class="bi bi-circle-fill"></i>{{ agent.enabled?'已启用 · '+(agent.model||'自定义 Agent'):'等待配置 Agent' }}</div><el-button @click="go('admin')">{{ agent.enabled?'管理 Agent':'配置学习教练' }} <i class="bi bi-arrow-up-right"></i></el-button></section></div></div>
        <p class="footer-note"><i class="bi bi-journal-check"></i> 知序 LearnLedger <span>一点一滴，自有回响。</span></p>
      </template>
      <template v-else-if="page==='tasks'||page==='admin'">
        <div class="page-heading"><div><p class="eyebrow">{{ page==='admin'?'WORKSPACE / ADMIN':'YOUR LEARNING JOURNEY' }}</p><h1>{{ page==='admin'?'管理工作台':'学习任务' }} <span class="heading-count">{{ tasks.length }}</span></h1><p class="muted">{{ page==='admin'?'创建学习内容、配置 Agent，让学习按自己的节奏发生。':'把想学的知识，拆成可以完成的小目标。' }}</p></div><div class="button-group"><el-button v-if="page==='admin'" @click="generateOpen=true"><i class="bi bi-stars"></i> Agent 生成任务</el-button><el-button type="primary" @click="newTask"><i class="bi bi-plus-lg"></i> 新建任务</el-button></div></div>
        <template v-if="page==='admin'"><div class="admin-shortcuts"><button class="panel shortcut-card" @click="settingsTab='agent';go('settings')"><span class="stat-icon purple"><i class="bi bi-robot"></i></span><div><strong>Agent 接入与提示词</strong><p>{{ agent.enabled?'已启用 · '+agent.model:'连接模型，开启学习评审' }}</p></div><i class="bi bi-arrow-up-right"></i></button><button class="panel shortcut-card" @click="settingsTab='api';go('settings')"><span class="stat-icon blue"><i class="bi bi-braces-asterisk"></i></span><div><strong>外部 Agent 发布 API</strong><p>通过接口创建、发布学习任务</p></div><i class="bi bi-arrow-up-right"></i></button></div><div class="section-title"><h2>全部任务管理</h2><span>发布前请检查 Markdown 与验收标准</span></div></template>
        <div class="filter-bar"><div class="filter-tabs"><button v-for="f in [{key:'all',label:'全部任务'},{key:'published',label:'进行中'},{key:'completed',label:'已完成'},{key:'draft',label:'草稿'}]" :key="f.key" :class="{active:filter===f.key}" @click="filter=f.key">{{ f.label }}<span v-if="f.key==='all'">{{ tasks.length }}</span></button></div><el-input v-model="search" class="search-input" placeholder="搜索任务、分类或知识点" clearable><template #prefix><i class="bi bi-search"></i></template></el-input></div>
        <div class="task-grid"><article v-for="task in visibleTasks" :key="task.id" class="panel task-card"><div class="card-top"><span class="mini-task-icon" :class="task.subject?.includes('数据')?'purple':'green'"><i :class="`bi bi-${taskIcon(task)}`"></i></span><el-tag :type="tagType(status(task))" effect="plain" size="small">{{ statusText(status(task)) }}</el-tag></div><h3><button @click="openTask(task)">{{ task.title }}</button></h3><p class="task-description">{{ task.description||task.content.replace(/[#*`>\[\]]/g,'').slice(0,88) }}</p><div class="tag-row"><span>{{ task.subject }}</span><span>{{ task.difficulty }}</span><span v-if="task.source==='agent'"><i class="bi bi-stars"></i> Agent</span></div><div class="task-card-meta"><span><i class="bi bi-clock"></i> {{ task.duration||30 }} 分钟</span><span class="task-reward"><i class="bi bi-coin"></i> +{{ task.points }}</span></div><div class="task-card-footer"><span>更新于 {{ date(task.updated_at) }}</span><div class="row-actions"><button class="icon-button" title="编辑任务" @click="editTask(task)"><i class="bi bi-pencil"></i></button><button class="icon-button" title="删除任务" @click="deleteTask(task)"><i class="bi bi-trash3"></i></button><button class="start-task" @click="openTask(task)">{{ task.status==='draft'?'查看草稿':completedIds.has(task.id)?'查看记录':'开始学习' }} <i class="bi bi-arrow-right"></i></button></div></div></article></div>
        <div v-if="!visibleTasks.length" class="panel empty-state"><i class="bi bi-search"></i><strong>这里还没有任务</strong><p>换一个筛选条件，或创建一个新的学习目标。</p><el-button type="primary" @click="newTask">创建任务</el-button></div>
      </template>
      <template v-else-if="page==='editor'">
        <div class="page-heading"><div><button class="back-button" @click="go('tasks')"><i class="bi bi-arrow-left"></i> 返回任务</button><h1>{{ editor.id?'编辑学习任务':'新的学习，从这里开始' }}</h1><p class="muted">用 Markdown 描述目标，用检查点定义完成。</p></div><div class="button-group"><el-button @click="fileInput.click()"><i class="bi bi-upload"></i> 导入 .md</el-button><el-button :loading="busy" @click="saveTask(false)">保存草稿</el-button><el-button type="primary" :loading="busy" @click="saveTask(true)"><i class="bi bi-send"></i> 发布任务</el-button></div><input ref="fileInput" type="file" accept=".md,.markdown,text/markdown,text/plain" hidden @change="importMd"/></div>
        <div class="editor-layout"><div class="editor-main"><section class="panel editor-meta"><label class="field-label">任务标题 <span>*</span></label><el-input v-model="editor.title" size="large" placeholder="例如：用 Vue 3 写出你的第一个组件" maxlength="200"/><div class="meta-row"><div class="form-field"><label>知识分类</label><el-select v-model="editor.subject" filterable allow-create><el-option v-for="c in categories" :key="c" :value="c"/></el-select></div><div class="form-field"><label>难度</label><el-select v-model="editor.difficulty"><el-option v-for="c in ['入门','进阶','挑战']" :key="c" :value="c"/></el-select></div><div class="form-field"><label>预计用时 / 分钟</label><el-input-number v-model="editor.duration" :min="5" :max="1440" :step="5" controls-position="right"/></div><div class="form-field"><label>金币奖励</label><el-input-number v-model="editor.points" :min="0" :max="1000" :step="10" controls-position="right"/></div></div><el-input v-model="editor.description" placeholder="一句话介绍这次学习任务（可选）" maxlength="300"/></section>
        <section class="panel markdown-panel"><div class="md-toolbar"><div class="toolbar-group"><button title="粗体" @click="wrap('**')"><i class="bi bi-type-bold"></i></button><button title="斜体" @click="wrap('*')"><i class="bi bi-type-italic"></i></button><button title="二级标题" @click="insert('\n## 标题\n')"><i class="bi bi-type-h2"></i></button><button title="代码块" @click="wrap('\n```js\n','\n```\n')"><i class="bi bi-code-slash"></i></button><button title="任务列表" @click="insert('\n- [ ] 待办事项\n')"><i class="bi bi-list-check"></i></button><button title="上传图片" :disabled="uploading" @click="imageInput.click()"><i class="bi bi-image"></i></button><button title="插入可完成检查点" @click="addCheckpoint"><i class="bi bi-patch-check"></i></button></div><div class="editor-view-tabs"><button v-for="v in [{key:'edit',label:'编辑'},{key:'split',label:'分栏'},{key:'preview',label:'预览'}]" :key="v.key" :class="{active:previewMode===v.key}" @click="previewMode=v.key">{{ v.label }}</button></div><input ref="imageInput" type="file" accept="image/png,image/jpeg,image/gif,image/webp" multiple hidden @change="onImage"/></div><div class="md-workspace" :class="{split:previewMode==='split'}"><textarea v-if="previewMode!=='preview'" ref="markdownInput" v-model="editor.content" class="markdown-input" aria-label="Markdown 任务正文" spellcheck="false" @paste="onPaste" @dragover.prevent @drop="onDrop"></textarea><div v-if="previewMode!=='edit'" class="markdown-preview markdown-body" v-html="renderMarkdown(editor.content)"></div></div><div class="md-footer"><span><i class="bi bi-markdown"></i> Markdown · 支持粘贴或拖入图片</span><span>{{ uploading?'正在保存图片…':autosaved||'编辑内容自动暂存到浏览器' }} · {{ editor.content.length }} 字符</span></div></section>
        <section class="panel acceptance-panel"><div class="panel-header"><div><h2><i class="bi bi-patch-check"></i> 验收标准</h2><p>截图和测试结果至少提交一种，Agent 根据实际证据判断</p></div></div><div class="acceptance-fields"><el-input v-model="editor.success_criteria" type="textarea" :rows="3" placeholder="例如：截图包含正常工作的计数器，+1 和重置按钮均能运行；测试覆盖初始状态与边界值。"/><div class="tag-row"><span><i class="bi bi-check2-square"></i> {{ checkpoints(editor.content).length }} 个可验证检查点</span><button class="link-button" @click="addCheckpoint">插入检查点</button></div></div></section></div>
        <aside class="editor-aside"><section class="panel aside-card"><div class="aside-heading"><i class="bi bi-lightbulb"></i><h3>写一个好任务</h3></div><p class="aside-desc">清晰的目标 + 动手练习 + 可验证的结果。</p><ol class="editor-tips"><li>说明要掌握什么</li><li>用检查点拆分验收标准</li><li>上传截图或填写测试输出</li><li>由 Agent 逐项评审</li></ol><div class="syntax-example"><span>可完成检查点</span><code>&lt;!-- sf:checkpoint id="step-1" title="完成练习" --&gt;</code></div></section><section class="panel aside-card"><div class="aside-heading"><i class="bi bi-images"></i><h3>任务图片</h3><el-tag size="small" type="info">{{ assets.length }}</el-tag></div><p class="aside-desc">图片保存在本地，正文引用占位符。只调整宽度，高度自动等比变化。</p><div v-for="asset in assets.filter(a=>imageIds(editor.content).includes(a.id))" :key="asset.id" class="placeholder-item"><img :src="asset.url" :alt="asset.name" class="placeholder-thumb"/><strong>{{ asset.name }}</strong><el-input-number :model-value="imageWidth(asset)" :min="40" :max="2400" :step="40" size="small" controls-position="right" @update:model-value="v=>resizeImage(asset,v)"/><small>宽度 px · 高度 auto</small></div><button class="upload-drop" :disabled="uploading" @click="imageInput.click()"><i class="bi bi-cloud-arrow-up"></i><span>{{ uploading?'上传中…':'选择图片或直接粘贴' }}</span><small>PNG / JPG / WebP / GIF · ≤ 5 MB</small></button></section><section class="panel aside-card"><div class="aside-heading"><i class="bi bi-filetype-md"></i><h3>随时带走你的知识</h3></div><p class="aside-desc">导出 Markdown 正文。图片占位符引用本地附件，完整备份见设置页。</p><el-button style="width:100%" @click="exportMd">导出 .md <i class="bi bi-download"></i></el-button></section></aside></div>
      </template>
      <template v-else-if="page==='detail'&&detail">
        <div class="page-heading"><div><button class="back-button" @click="go('tasks')"><i class="bi bi-arrow-left"></i> 所有学习任务</button><div class="detail-title"><h1>{{ detail.title }}</h1><el-tag :type="tagType(status(detail))" effect="plain">{{ statusText(status(detail)) }}</el-tag></div><p class="muted">{{ detail.subject }} · {{ detail.difficulty }} · 预计 {{ detail.duration||30 }} 分钟</p></div><el-button @click="editTask(detail)"><i class="bi bi-pencil"></i> 编辑任务</el-button></div>
        <div class="detail-layout"><div class="detail-content"><section class="panel"><div class="file-heading"><i class="bi bi-markdown"></i> 任务说明.md <span>{{ detail.source==='agent'?'由 Agent 创建':'我的学习任务' }}</span></div><div class="markdown-body detail-markdown" v-html="renderMarkdown(detail.content)"></div></section><section v-if="detail.success_criteria" class="panel criteria-card"><h3><i class="bi bi-patch-check"></i> 验收标准</h3><p>{{ detail.success_criteria }}</p></section><section class="panel submit-panel"><div class="panel-header"><div><h2><i class="bi bi-cloud-arrow-up"></i> 提交学习成果</h2><p>让成果说话，给自己的努力一个回响</p></div></div><div v-if="detail.status==='draft'" class="empty-state"><p>当前任务是草稿，发布后即可提交成果。</p><el-button type="primary" @click="editTask(detail)">去编辑与发布</el-button></div><div v-else class="submission-form"><div v-if="taskCheckpoints.length" class="checkpoint-list"><el-checkbox v-for="c in taskCheckpoints" :key="c.id" :model-value="checkedIds.includes(c.id)" @change="v=>checkedIds=v?[...checkedIds,c.id]:checkedIds.filter(id=>id!==c.id)">{{ c.title }}</el-checkbox></div><div class="form-field"><label>学习总结</label><el-input v-model="answer" type="textarea" :rows="3" placeholder="你是如何完成的？还有哪些收获或疑惑？"/></div><div class="form-field"><label>运行截图</label><div class="proof-grid"><div v-for="(asset,index) in proofAssets" :key="asset.id" class="proof-image"><a :href="asset.url" target="_blank" rel="noopener"><img :src="asset.url" :alt="asset.name"/></a><button aria-label="移除截图" @click="proofAssets.splice(index,1)"><i class="bi bi-x"></i></button></div><button class="upload-drop proof-upload" :disabled="uploading" @click="proofInput.click()"><i class="bi bi-image"></i><span>上传成果截图</span><small>单张 ≤ 5 MB</small></button></div><input ref="proofInput" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden @change="addProof"/></div><div class="form-field"><label>测试输出 <span class="muted">（与截图至少提交一种）</span></label><el-input v-model="testOutput" type="textarea" :rows="5" placeholder="粘贴测试命令、测试用例和实际输出结果。Agent 将判断它们是否满足任务标准。" class="code-input"/></div><div class="submit-actions"><span class="muted"><i class="bi bi-shield-check"></i> 通过评审后自动奖励，同一任务仅一次</span><el-button type="primary" :loading="submitBusy||uploading" @click="submit"><i class="bi bi-send"></i> 提交给 Agent</el-button></div></div></section>
        <section v-if="detail.submissions?.length" class="panel history-panel"><div class="panel-header"><h2>提交与反馈</h2><span class="muted">{{ detail.submissions.length }} 次提交</span></div><article v-for="s in detail.submissions" :key="s.id" class="submission-card"><div class="submission-top"><el-tag :type="tagType(s.status)" effect="plain">{{ statusText(s.status) }}</el-tag><span>#{{ s.id }} · {{ date(s.created_at) }}</span><strong v-if="s.status==='completed'||s.status==='needs_revision'">{{ s.score }} 分</strong></div><p>{{ s.feedback||'成果已保存，等待 Agent 评审。' }}</p><p v-if="s.agent_error" class="agent-error">{{ s.agent_error }}</p><div v-if="s.analysis" class="analysis-box"><strong><i class="bi bi-lightbulb"></i> 错题分析</strong><p>{{ s.analysis }}</p></div><div v-if="s.next_step" class="next-step"><strong>下一步</strong><p>{{ s.next_step }}</p></div><div v-if="s.checkpoints?.length" class="checkpoint-results"><div v-for="c in s.checkpoints" :key="c.id"><i :class="`bi bi-${c.completed?'check-circle':'exclamation-circle'}`"></i><code>{{ c.id }}</code><span>{{ c.feedback }}</span></div></div><details class="submitted-evidence"><summary>查看提交内容</summary><p v-if="s.answer">{{ s.answer }}</p><pre v-if="s.test_output">{{ s.test_output }}</pre><div class="proof-grid"><a v-for="id in s.attachment_ids||[]" :key="id" :href="`/api/uploads/${id}/file`" target="_blank" rel="noopener"><img class="evidence-preview" :src="`/api/uploads/${id}/file`" alt="提交截图"/></a></div></details><el-button v-if="['pending','error'].includes(s.status)" size="small" :loading="submitBusy" @click="retry(s)"><i class="bi bi-arrow-repeat"></i> {{ s.status==='error'?'重新评审':'发起评审' }}</el-button></article></section></div><aside class="detail-aside"><section class="panel reward-card"><span class="reward-coin"><i class="bi bi-coin"></i></span><span class="eyebrow">完成这个小目标</span><h2>+{{ detail.points }} <small>金币</small></h2><p>{{ completedIds.has(detail.id)?'你已完成这个任务，继续复习巩固吧。':'完成评审后，金币将自动记入成长账本。' }}</p><el-tag v-if="completedIds.has(detail.id)" type="success" effect="plain"><i class="bi bi-check2"></i> 已完成</el-tag></section><section class="panel aside-card"><div class="aside-heading"><i class="bi bi-robot"></i><h3>Agent 评审说明</h3></div><p class="aside-desc">会检查你提交的截图、测试输出和每一个验收点，并返回具体反馈。</p><p class="aside-desc" v-if="!agent.enabled">当前未启用 Agent，提交将暂存为“待评审”。</p><el-button text type="primary" @click="settingsTab='agent';go('settings')">管理 Agent <i class="bi bi-arrow-right"></i></el-button></section></aside></div>
      </template>
      <template v-else-if="page==='reviews'">
        <div class="page-heading"><div><p class="eyebrow">REFLECT, REFINE, REPEAT</p><h1>每一次反馈，都是进步的线索</h1><p class="muted">回看提交记录，把不确定的知识变成确定的能力。</p></div><el-tag type="warning" effect="plain">{{ reviewCounts.revision }} 个待改进 · {{ reviewCounts.pending }} 个待评审</el-tag></div><div class="review-list"><article v-for="s in submissions" :key="s.id" class="panel review-card"><div class="submission-top"><el-tag :type="tagType(s.status)" effect="plain">{{ statusText(s.status) }}</el-tag><span>{{ date(s.created_at) }}</span><strong v-if="['completed','needs_revision'].includes(s.status)">{{ s.score }} 分</strong></div><h3>{{ s.title||s.task_title||'学习任务' }}</h3><p>{{ s.feedback||'你的学习成果已保存，等待 Agent 评审。' }}</p><p v-if="s.agent_error" class="agent-error">{{ s.agent_error }}</p><div v-if="s.analysis" class="analysis-box"><strong>错题分析</strong><p>{{ s.analysis }}</p></div><p v-if="s.next_step" class="next-step">下一步：{{ s.next_step }}</p><div class="review-actions"><el-button v-if="['pending','error'].includes(s.status)" :loading="submitBusy" @click="retry(s)">重新评审</el-button><el-button type="primary" plain @click="openTask({id:s.task_id})">回到任务 <i class="bi bi-arrow-right"></i></el-button></div></article></div><div v-if="!submissions.length" class="panel empty-state"><i class="bi bi-chat-square-heart"></i><strong>你的第一份学习反馈，正在路上</strong><p>完成一个任务，提交截图或测试结果吧。</p><el-button type="primary" @click="go('tasks')">去学习</el-button></div>
      </template>
      <template v-else-if="page==='achievements'">
        <div class="page-heading"><div><p class="eyebrow">A LITTLE BETTER, EVERY DAY</p><h1>成长，值得被看见</h1><p class="muted">每一枚徽章，都记录着你认真学习的某个瞬间。</p></div><span class="achievement-score"><i class="bi bi-trophy"></i><strong>{{ unlockedCount }} / {{ achievements.length }}</strong> 已解锁</span></div><div class="panel achievement-hero"><div><span class="eyebrow">你的成长账本</span><h2>{{ unlockedCount?'继续点亮下一枚成就':'从第一步，走向更多可能' }}</h2><p>完成任务、不断练习，积累属于你的知识与奖励。</p><button class="link-button" @click="showCoins"><i class="bi bi-coin"></i> 当前 {{ dashboard.coins||0 }} 枚金币 · 查看账本 <i class="bi bi-arrow-right"></i></button></div><div class="hero-medal"><i class="bi bi-award"></i></div></div><div class="achievements-grid"><article v-for="a in achievements" :key="a.key||a.id" class="panel achievement-card" :class="{locked:!a.unlocked}"><div class="achievement-icon"><i :class="`bi ${a.icon||'bi-award'}`"></i><i v-if="a.unlocked" class="bi bi-check-circle-fill unlocked-dot"></i></div><h3>{{ a.title }}</h3><p>{{ a.description }}</p><span v-if="a.unlocked" class="unlocked-label"><i class="bi bi-check2-circle"></i> 已解锁 · {{ date(a.unlocked_at) }}</span><div v-else class="achievement-progress"><el-progress :percentage="Math.min(100,Number(a.progress)||0)" :show-text="false" :stroke-width="5" :color="settings.accent"/><span>{{ a.progress_label || ((a.current || 0) + ' / ' + (a.target || 1)) }}</span></div></article></div>
      </template>
      <template v-else-if="page==='settings'">
        <div class="page-heading"><div><p class="eyebrow">MAKE IT YOURS</p><h1>你的空间，你来定义</h1><p class="muted">选择舒适的外观，连接合适的学习伙伴。</p></div></div><div class="settings-layout"><nav class="panel settings-nav"><button v-for="item in [{key:'appearance',label:'外观与主题',icon:'palette'},{key:'agent',label:'Agent 配置',icon:'robot'},{key:'api',label:'开放 API',icon:'braces'},{key:'data',label:'数据与备份',icon:'database'}]" :key="item.key" :class="{active:settingsTab===item.key}" @click="settingsTab=item.key"><i :class="`bi bi-${item.icon}`"></i>{{ item.label }}<i class="bi bi-chevron-right"></i></button></nav><section class="panel settings-content">
        <template v-if="settingsTab==='appearance'"><div class="settings-section"><h2>外观与主题</h2><p>找到最适合你的学习氛围。</p><div class="theme-options"><button :class="{selected:settings.theme==='light'}" @click="settings.theme='light'"><div class="theme-preview light-preview"><i></i><div><b></b><b></b><b></b></div></div><span><i class="bi bi-sun"></i> 浅色模式 <i v-if="settings.theme==='light'" class="bi bi-check-circle-fill"></i></span></button><button :class="{selected:settings.theme==='dark'}" @click="settings.theme='dark'"><div class="theme-preview dark-preview"><i></i><div><b></b><b></b><b></b></div></div><span><i class="bi bi-moon-stars"></i> 深色模式 <i v-if="settings.theme==='dark'" class="bi bi-check-circle-fill"></i></span></button></div><div class="setting-row column"><div><strong>主题色</strong><span>按钮、进度和选中状态，使用你喜欢的颜色</span></div><div class="color-options"><button v-for="color in ['#238636','#0969da','#8250df','#bf3989','#bc4c00','#0e8a88']" :key="color" class="color-dot" :class="{selected:settings.accent===color}" :style="{background:color}" :aria-label="`选择主题色${color}`" @click="settings.accent=color"><i v-if="settings.accent===color" class="bi bi-check-lg"></i></button><el-color-picker v-model="settings.accent" :predefine="['#238636','#0969da','#8250df']"/><code>{{ settings.accent }}</code></div></div><div class="setting-row"><div><strong>紧凑布局</strong><span>减少卡片与列表之间的间距</span></div><el-switch v-model="settings.compact_mode"/></div><div class="settings-actions"><span class="muted">外观即时预览，保存后同步至本地数据库。</span><el-button type="primary" :loading="busy" @click="saveSettings">保存偏好</el-button></div></div></template>
        <template v-else-if="settingsTab==='agent'"><div class="settings-section"><h2>连接你的学习 Agent</h2><p>支持 OpenAI 兼容接口与自定义 Webhook。API Key 仅保存在服务端。</p><div class="setting-row"><div><strong>启用 Agent 评审</strong><span>关闭时提交会保存为待评审</span></div><el-switch v-model="agent.enabled"/></div><div class="form-field"><label>接口协议</label><el-select v-model="agent.provider"><el-option label="OpenAI 兼容 · Chat Completions" value="openai-compatible"/><el-option label="自定义 Webhook" value="webhook"/></el-select></div><div class="form-field"><label>完整 API 地址</label><el-input v-model="agent.endpoint" placeholder="https://your-provider.com/v1/chat/completions"/><small class="muted">截图识别需要选择支持视觉输入的模型。</small></div><div class="form-field"><label>模型名称</label><el-input v-model="agent.model" placeholder="填写服务商提供的模型名称"/></div><div class="form-field"><label>API Key <el-tag v-if="agent.has_api_key" size="small" type="success">已保存</el-tag></label><el-input v-model="apiKey" type="password" show-password :placeholder="agent.has_api_key?'留空保留当前密钥':'输入 API Key（可选，取决于服务商）'" autocomplete="new-password"/></div><div class="form-field"><label>评审系统提示词</label><el-input v-model="agent.system_prompt" type="textarea" :rows="12"/><small class="muted">内置提示词要求逐检查点评审、依据证据判定，并返回错题原因和修正步骤。</small></div><div class="settings-actions"><span class="muted">配置保存后，对待评审提交点击“重新评审”即可。</span><el-button type="primary" :loading="busy" @click="saveAgent">保存 Agent 配置</el-button></div></div></template>
        <template v-else-if="settingsTab==='api'"><div class="settings-section"><h2>让 Agent 为你发布学习任务</h2><p>外部 Agent 可使用专属 Bearer 令牌创建任务。</p><div class="api-endpoint"><el-tag type="success">POST</el-tag><code>http://127.0.0.1:3001/api/agent/publish</code></div><div class="form-field"><label>Agent 发布令牌</label><el-button v-if="!publishToken" @click="loadToken"><i class="bi bi-key"></i> 显示本地发布令牌</el-button><el-input v-else :model-value="publishToken" type="password" show-password readonly><template #append><el-button @click="copy(publishToken)">复制</el-button></template></el-input></div><h3>请求示例</h3><pre class="api-example">POST /api/agent/publish
Authorization: Bearer &lt;发布令牌&gt;
Content-Type: application/json

{
  "title": "理解 JavaScript 事件循环",
  "subject": "JavaScript",
  "difficulty": "进阶",
  "points": 40,
  "duration": 30,
  "status": "published",
  "content": "# 学习目标\n说明宏任务与微任务。\n\n&lt;!-- sf:checkpoint id=\"event-loop\" title=\"提交测试结果\" --&gt;",
  "success_criteria": "解释执行顺序并提供测试输出"
}</pre><p class="muted">发布令牌用于创建任务。管理配置通过本机工作台完成。更多接口见项目 README。</p></div></template>
        <template v-else><div class="settings-section"><h2>数据与备份</h2><p>学习记录保存在本机 SQLite，图片保存在本地上传目录。</p><div class="data-summary"><i class="bi bi-database-check"></i><div><strong>SQLite 本地数据库</strong><span>{{ tasks.length }} 个学习任务 · {{ submissions.length }} 次成果提交</span></div><el-tag type="success" effect="plain">已连接</el-tag></div><div class="setting-row"><div><strong>导出完整数据</strong><span>包含任务、提交、图片及金币记录；不包含 Agent 密钥。</span></div><el-button @click="exportData"><i class="bi bi-download"></i> 导出 JSON</el-button></div><p class="muted">可定期备份 server/data 文件夹（其中 uploads 为图片附件）。图片占位符需与附件一起保留。</p></div></template>
        </section></div>
      </template>
    </div>
  </main>
  <el-dialog v-model="generateOpen" title="让 Agent 规划下一段学习" width="540px" class="responsive-dialog" :close-on-click-modal="!generateBusy"><p class="muted">输入学习目标，Agent 会生成可编辑的任务草稿，检查后即可发布。</p><div v-if="!agent.enabled" class="inline-notice"><i class="bi bi-info-circle"></i> 请先在偏好设置中启用并配置 Agent。</div><div class="form-field"><label>你想学什么？</label><el-input v-model="generator.topic" type="textarea" :rows="3" placeholder="例如：我了解 HTML/CSS，想用一周掌握 Vue 3 的核心概念"/></div><div class="meta-row"><div class="form-field"><label>分类</label><el-select v-model="generator.subject" filterable allow-create><el-option v-for="c in categories" :key="c" :value="c"/></el-select></div><div class="form-field"><label>难度</label><el-select v-model="generator.difficulty"><el-option v-for="d in ['入门','进阶','挑战']" :key="d" :value="d"/></el-select></div></div><div class="form-field"><label>任务数量</label><el-input-number v-model="generator.count" :min="1" :max="5"/></div><template #footer><el-button @click="generateOpen=false">取消</el-button><el-button type="primary" :loading="generateBusy" :disabled="!agent.enabled" @click="generate"><i class="bi bi-stars"></i> 生成学习任务</el-button></template></el-dialog>
  <el-dialog v-model="coinOpen" title="我的成长账本" width="620px" class="responsive-dialog"><div class="ledger-balance"><i class="bi bi-coin"></i><strong>{{ coins.total }}</strong><span>枚金币 · 每一枚都来自你的进步</span></div><div v-for="tx in coins.transactions" :key="tx.id" class="ledger-row"><span class="ledger-icon"><i class="bi bi-check2"></i></span><div><strong>{{ tx.reason }}</strong><span>{{ date(tx.created_at) }}</span></div><b class="coin-text">+{{ tx.amount }}</b></div><div v-if="!coins.transactions.length" class="empty-state"><p>通过第一个学习任务，开启你的金币账本。</p></div></el-dialog>
</div>
</template>






